def import_uebermittelte_orders(datei: str, output: str, tabelle: str, database: str = DATABASE) -> bool:
    """Importiert übermittelte Bestellungen aus einer CSV-datei in die Datenbank.

    Args:
        datei: Der Pfad zur CSV-datei.
        output: Der Name der Ausgabedatei nach dem Import.
        tabelle: Der Name der Zieltabelle.
        database: Der Name der Datenbank.

    Returns:
        True wenn der Import erfolgreich war.
    """
    output_file = None
    try:
        df = pd.read_csv(datei, usecols=[0], dtype=str)
        first_column_name = df.columns[0]
        df = df.rename(columns={first_column_name: "OrderID"})
        df = df.drop_duplicates(subset="OrderID", keep="first")

        output_file = f"{output}.csv"
        df.to_csv(output_file, index=False)
        logger.info(f"CSV-datei '{output_file}' mit einzigartigen OrderIDs erstellt.")

        import_table(output_file, tabelle, "Nein")
        return True

    except Exception as e:
        logger.error(f"Fehler beim Verarbeiten der datei '{datei}': {e}")
        raise

    finally:
        if output_file:
            try:
                os.remove(output_file)
                logger.info(f"datei '{output_file}' wurde nach dem Import gelöscht.")
            except Exception as e:
                logger.error(f"Fehler beim Löschen der datei '{output_file}': {e}")


def update_orderauschluss(order_date: str, database: str = DATABASE) -> bool:
    """Aktualisiert die OrderAusschluss-tabelle für OrderID 0.

    Args:
        order_date: Das Datum für die Spalte OrderDate.
        database: Der Name der Datenbank.

    Returns:
        True wenn die Aktualisierung erfolgreich war.
    """
    connection = None
    try:
        connection = connect_to_db(database)
        if not connection:
            logger.error("Keine Datenbankverbindung hergestellt!")
            return False

        with connection.cursor() as cursor:
            sql_query = """
                INSERT INTO tb_order_ausschluss (OrderID, AccountID, OrderDate)
                VALUES (0, NULL, ?)
                ON DUPLICATE KEY UPDATE
                    AccountID = VALUES(AccountID),
                    OrderDate = VALUES(OrderDate)
            """
            cursor.execute(sql_query, (order_date,))
            connection.commit()
            logger.info(f"OrderID 0 erfolgreich aktualisiert mit OrderDate: {order_date}")
            return True

    except Exception as e:
        logger.error(f"Fehler beim Einfügen/Aktualisieren: {e}")
        raise

    finally:
        if connection:
            connection.close()


def fakturabfrage(
    prozedur: str, start_date: str, end_date: str, pfad: str, bereinigen: str, format_output: str
) -> str | None:
    """Führt eine Fakturabfrage durch und exportiert die Ergebnisse.

    Args:
        prozedur: Name der Stored Procedure.
        STARTDATE: Startdatum für die Abfrage.
        ENDDATE: Enddatum für die Abfrage.
        Pfad: Zielpfad für den Export.
        Bereinigen: 'Ja' oder 'Nein'.
        format_output: Ausgabeformat ('Excel', 'CSV' oder 'Excel,CSV').

    Returns:
        Dateiname der CSV-datei oder None.
    """
    connection = None
    try:
        connection = connect_to_db()
        if not connection:
            raise ConnectionError("Keine Datenbankverbindung hergestellt!")

        output_file_excel = None
        output_file_csv = None

        with connection.cursor() as cursor:
            cursor.callproc(prozedur, (start_date, end_date))
            connection.commit()
            logger.info("Stored Procedure '%s' erfolgreich fuer %s bis %s ausgefuehrt.", prozedur, start_date, end_date)

        if str(bereinigen) == "Ja":
            with connection.cursor() as cursor:
                cursor.callproc("Bereinigung_bereits_uebermittele_Orders")
                connection.commit()
                logger.info("Daten wurden um bereits übergebene Orders bereinigt.")

        logger.info("Export wird gestartet.")
        with connection.cursor() as cursor:
            cursor.execute("SELECT * FROM tb_orderreport_export")
            columns = [col[0] for col in cursor.description]
            data = cursor.fetchall()

        df = pd.DataFrame(data, columns=columns)
        timestamp = datetime.now(TIMEZONE).strftime("%Y%m%d-%H%M%S")

        format_lower = str(format_output).lower()

        if format_lower in ("excel", "excel,csv"):
            output_file_excel = f"OrderReport-{timestamp}_{prozedur}.xlsx"
            df.to_excel(os.path.join(pfad, output_file_excel), index=False)

        if format_lower in ("csv", "excel,csv"):
            output_file_csv = f"OrderReport-{timestamp}_{prozedur}.csv"
            df.to_csv(os.path.join(pfad, output_file_csv), index=False, encoding="utf-8-sig")

        exported = [f for f in [output_file_excel, output_file_csv] if f]
        if exported:
            logger.info(f"Daten erfolgreich exportiert: {', '.join(exported)}")
        else:
            logger.info("Kein Export erfolgt.")

        abfrage = get_query_text("ORDER_VKORG")
        df_result = execute_dataframe_query(abfrage)
        if df_result is not None and not df_result.empty:
            logger.info(f"ORDER_VKORG Abfrage erfolgreich: {len(df_result)} Zeilen")
        else:
            logger.error(f"Fehler bei der Ausführung der Abfrage: {abfrage}")

        return output_file_csv

    except Exception as e:
        logger.error(f"Fehler bei der Ausführung der Stored Procedure oder der Datenabfrage: {e}")
        raise

    finally:
        if connection:
            connection.close()


def faktur(
    prozedur: str,
    start_date: str,
    end_date: str,
    pfad: str,
    bereinigen: str,
    format_output: str,
    order_auschluss: bool = True,
    kpi: bool = True,
    uebermittelte_orders: bool = True,
) -> tuple[str, str]:
    """Führt die Fakturierung durch inkl. Validierung, Export und KPI.

    Args:
        prozedur: Name der auszuführenden prozedur.
        start_date: Startdatum im Format 'YYYY-MM-DD HH:MM:SS'.
        end_date: Enddatum im Format 'YYYY-MM-DD HH:MM:SS'.
        pfad: Zielpfad für exportierte Dateien.
        bereinigen: 'Ja' oder 'Nein'.
        format_output: Exportformat ('Excel', 'CSV' oder 'Excel,CSV').
        order_auschluss: Ob tb_order_ausschluss aktualisiert werden soll.
        KPI: Ob KPIs berechnet werden sollen.
        uebermittelte_orders: Ob übermittelte Orders importiert werden sollen.

    Returns:
        (filename, import_ordner) für D365-Upload. Wirft Exception bei Fehlern.
    """
    dt_start = coerce_to_datetime(start_date, "start_date")
    dt_end = coerce_to_datetime(end_date, "end_date")

    if dt_start > dt_end:
        raise ValueError("Das Enddatum darf nicht vor dem Startdatum liegen.")

    tables = {
        "tb_orderreport_faktur": "tabelle tb_orderreport_faktur",
        "tb_subscriptionsreport_ff": "tabelle tb_subscriptionsreport_ff",
        "tb_accountreport_faktur": "tabelle tb_accountreport_faktur",
        "tb_orderreport_refund": "tabelle tb_orderreport_refund",
    }
    for table, label in tables.items():
        min_date = coerce_to_datetime(status_table(table, "MIN"), f"{table}.MIN")
        max_date = coerce_to_datetime(status_table(table, "MAX"), f"{table}.MAX")
        if dt_start <= min_date:
            raise ValueError(f"Das Startdatum liegt vor dem ersten Eintrag in der {label}.")
        elif dt_end >= max_date:
            raise ValueError(f"Das Enddatum liegt nach dem letzten Eintrag in der {label}.")

    if order_auschluss:
        end_date_ord_ausschluss = f"{end_date}.000"
        update_orderauschluss(end_date_ord_ausschluss)
        logger.info("tabelle tb_order_ausschluss wurde aktualisiert")

    try:
        logger.info(f"Starte Fakturabfrage {prozedur} für den Zeitraum {start_date} bis {end_date}")
        output_file_csv = fakturabfrage(prozedur, start_date, end_date, pfad, bereinigen, format_output)
        logger.info(f"CSV-Dateiname: {output_file_csv}")
    except Exception as e:
        logger.error(f"Fehler bei der Fakturabfrage: {e}", exc_info=True)
        raise

    try:
        if kpi:
            logger.info("Berechne KPI")
            kpi_name = f"KPI_OrderReport_{datetime.now(TIMEZONE).strftime('%Y%m%d')}"
            kpi_query = get_query_text("KPI_UMSATZ_ORDERREPORT")
            datenbankabfrage_mit_export(kpi_query, kpi_name, pfad, "Excel")
    except Exception as e:
        logger.error(f"Fehler bei der KPI Berechnung: {e}", exc_info=True)
        raise

    try:
        if uebermittelte_orders and output_file_csv:
            success = import_uebermittelte_orders(
                os.path.join(pfad, output_file_csv), "uebermittelte_Orders", "tb_uebermittelte_orders"
            )
            if success:
                logger.info("Übermittelte Orders erfolgreich importiert")
            else:
                logger.error("Fehler beim Import der übermittelten Orders")
    except Exception as e:
        logger.error(f"Fehler beim Verarbeiten der datei: {e}", exc_info=True)
        raise

    if not output_file_csv:
        raise RuntimeError("Fakturabfrage hat keine CSV-datei erzeugt")
    return (output_file_csv, pfad)


def praemienexport(prozedur: str, welt: str, start_date: str, end_date: str, pfad: str, name: str) -> None:
    """Exportiert Prämien-Daten basierend auf den angegebenen Parametern.

    Args:
        prozedur: Name der prozedur ('Sachpraemien' oder 'Hardware').
        welt: Welt ('MS' oder 'OWL').
        start_date: Startdatum im Format 'YYYY-MM-DD'.
        end_date: Enddatum im Format 'YYYY-MM-DD'.
        pfad: Zielpfad für die exportierten Dateien.
        name: Name der Ausgabedatei ohne Erweiterung.
    """
    if start_date > end_date:
        raise ValueError("Das Enddatum darf nicht vor dem Startdatum liegen.")

    # Eingabevalidierung gegen SQL-Injection
    if prozedur not in ALLOWED_PROZEDUREN:
        raise ValueError(f"Ungültige prozedur: {prozedur}. Erlaubt: {ALLOWED_PROZEDUREN}")
    if welt not in ALLOWED_WELTEN:
        raise ValueError(f"Ungültige Welt: {welt}. Erlaubt: {ALLOWED_WELTEN}")
    if not re.match(r"^\d{4}-\d{2}-\d{2}$", start_date) or not re.match(r"^\d{4}-\d{2}-\d{2}$", end_date):
        raise ValueError(f"Ungültiges Datumsformat: start_date={start_date}, end_date={end_date}")

    try:
        datenbankabfrage_mit_export(
            pfad=pfad, output=name, sql_abfrage=f"CALL {prozedur}('{welt}','{start_date}','{end_date}')", typ="EXCEL"
        )
    except Exception as e:
        logger.error(f"Fehler beim Export der Daten: {e}", exc_info=True)
        raise


def _validate_required_field(
    row: list[str], column_name: str, line_number: int, reject_leer: bool = False
) -> tuple[bool, str] | None:
    """Prüft ob ein Pflichtfeld gefüllt ist.

    Args:
        row: Die CSV-Zeile als Liste.
        column_name: Name der Spalte (muss in EXPECTED_HEADERS existieren).
        line_number: Zeilennummer für Fehlermeldung.
        reject_leer: Ob der Wert 'leer' als ungültig gelten soll.

    Returns:
        (False, Fehlermeldung) bei Fehler, None wenn ok.
    """
    idx = _HEADER_INDEX[column_name]
    value = row[idx] if idx < len(row) else ""

    if value is None or value.strip() == "":
        return False, f"Fehler in Zeile {line_number}: '{column_name}' muss immer gefüllt sein."

    if reject_leer and value.lower() == "leer":
        return False, f"Fehler in Zeile {line_number}: '{column_name}' muss immer gefüllt sein."

    return None


def _validate_datetime_field(row: list[str], column_name: str, line_number: int) -> tuple[bool, str] | None:
    """Prüft ob ein Datumsfeld das erwartete Format hat.

    Returns:
        (False, Fehlermeldung) bei Fehler, None wenn ok.
    """
    idx = _HEADER_INDEX[column_name]
    try:
        datetime.strptime(row[idx].strip(), "%Y-%m-%d %H:%M:%S")
    except Exception:
        return False, (
            f"Fehler in Zeile {line_number}: '{column_name}' hat ein ungültiges Format. Erwartet: YYYY-MM-DD HH:MM:SS."
        )
    return None


def check_csv_file(file_path: str) -> tuple[bool, str]:
    """Überprüft eine CSV-datei auf Struktur und Inhaltsanforderungen.

    Prüft:
    - UTF-8 BOM Encoding
    - Dateiname beginnt mit 'orderreport'
    - Spaltenüberschriften und -reihenfolge
    - Pflichtfelder gefüllt
    - Datumsformate korrekt

    Args:
        file_path: Pfad zur CSV-datei.

    Returns:
        (True, Erfolgsmeldung) oder (False, Fehlermeldung).
    """
    with open(file_path, "rb") as bin_file:
        bom = bin_file.read(3)
        if bom != b"\xef\xbb\xbf":
            return False, "datei ist nicht in UTF-8 BOM codiert."

    required_prefix = "orderreport"
    file_name = os.path.basename(file_path)
    if not file_name.lower().startswith(required_prefix):
        return False, f"Dateiname muss mit '{required_prefix}' beginnen. Gefunden: {file_name}"

    with open(file_path, newline="", encoding="utf-8-sig") as csvfile:
        reader = csv.reader(csvfile)
        headers = next(reader, None)
        if headers is None:
            return False, "Die CSV-datei ist leer."
        rows = list(reader)

    if headers != EXPECTED_HEADERS:
        differences = []
        min_len = min(len(EXPECTED_HEADERS), len(headers))
        for i in range(min_len):
            if EXPECTED_HEADERS[i] != headers[i]:
                differences.append(f"Spalte {i + 1}: erwartet '{EXPECTED_HEADERS[i]}', gefunden '{headers[i]}'")
        if len(headers) != len(EXPECTED_HEADERS):
            differences.append(f"Anzahl der Spalten: erwartet {len(EXPECTED_HEADERS)}, gefunden {len(headers)}")
        return False, f"Spaltenüberschrift oder -anordnung ist falsch. Fehler: {differences}"

    required_fields = [
        ("CustomClientUserId", False),
        ("PeriodStartDate", False),
        ("PeriodEndDate", False),
        ("OrderCode", True),
        ("PVA", True),
        ("Rechnungsdruck", True),
        ("VkOrg", True),
        ("ZAbotyp", False),
    ]

    datetime_fields = ["PeriodStartDate", "PeriodEndDate"]

    for line_number, row in iter_with_progress(logger, enumerate(rows, start=2), len(rows), "CSV-Zeilenpruefung"):
        if len(row) < len(EXPECTED_HEADERS):
            return False, f"Fehler in Zeile {line_number}: unvollständige Zeile."

        for field_name, reject_leer in required_fields:
            error = _validate_required_field(row, field_name, line_number, reject_leer)
            if error:
                return error

        for field_name in datetime_fields:
            error = _validate_datetime_field(row, field_name, line_number)
            if error:
                return error

    return True, "CSV-datei entspricht den Kriterien."


def send_faktur_email(
    subject: str,
    attachments: list[str | Path] | None = None,
    error_message: str | None = None,
) -> None:
    """Sendet eine Fakturierungs-Zusammenfassung per E-Mail.

    Liest Sender aus der Umgebungsvariable NOTIFICATION_SENDER.
    Der Body wird automatisch aus der VkOrg-Auswertung erzeugt, oder zeigt
    die Fehlermeldung wenn error_message übergeben wird.

    Args:
        subject: Betreff der E-Mail.
        attachments: Optionale Liste von Dateipfaden als Anhang.
        error_message: Fehlermeldung bei fehlgeschlagenem Prozess.
    """
    if error_message:
        body = f"""
        <html><body style="font-family:Segoe UI,Arial,sans-serif;font-size:14px;color:#333;">
        <h3 style="margin-bottom:8px;color:#c0392b;">Fehler bei der Fakturierung</h3>
        <p style="background:#fdf2f2;border-left:4px solid #c0392b;padding:12px 16px;border-radius:3px;">
            {error_message}
        </p>
        </body></html>
        """
    else:
        query = """
            SELECT
                CASE
                    WHEN vkorg IN ('AH', 'OT', 'WN') THEN 'WN'
                    ELSE vkorg
                END AS VkOrg,
                COUNT(rep.OrderID) AS Anzahl
            FROM
                tb_orderreport_export rep
            GROUP BY
                CASE
                    WHEN vkorg IN ('AH', 'OT', 'WN') THEN 'WN'
                    ELSE vkorg
                END
        """
        df = execute_dataframe_query(query)

        if df is not None and not df.empty:
            total = df["Anzahl"].sum()
            rows_html = "".join(
                f"<tr><td style='padding:6px 16px;border-bottom:1px solid #e0e0e0;'>{row.VkOrg}</td>"
                "<td style='padding:6px 16px;border-bottom:1px solid #e0e0e0;text-align:right;'>"
                f"{row.Anzahl:,}</td></tr>"
                for row in df.itertuples()
            )
            body = f"""
            <html><body style="font-family:Segoe UI,Arial,sans-serif;font-size:14px;color:#333;">
            <h3 style="margin-bottom:8px;">VkOrg-Auswertung</h3>
            <table style="border-collapse:collapse;min-width:220px;">
                <thead>
                    <tr>
                        <th style="padding:8px 16px;text-align:left;border-bottom:2px solid #333;">VkOrg</th>
                        <th style="padding:8px 16px;text-align:right;border-bottom:2px solid #333;">Anzahl</th>
                    </tr>
                </thead>
                <tbody>{rows_html}</tbody>
                <tfoot>
                    <tr style="background:#f5f5f5;font-weight:bold;">
                        <td style="padding:8px 16px;">Gesamt</td>
                        <td style="padding:8px 16px;text-align:right;">{total:,}</td>
                    </tr>
                </tfoot>
            </table>
            </body></html>
            """
        else:
            body = "<p>Keine Daten gefunden.</p>"

    sender = os.environ.get("NOTIFICATION_SENDER", "")
    recipients_raw = RECIPTENTS_FAKTUR
    recipients = [r.strip() for r in recipients_raw.split(",") if r.strip()]

    mailer = mailer_from_encrypted_env(
        sender=sender,
        default_recipients=recipients,
    )
    mailer.send(
        subject=subject,
        body=body,
        body_type="HTML",
        attachments=attachments,
    )
